def ingest_notification(redis_client, producer, event: dict) -> str:
    key = f"idemp:{event['idempotency_key']}"
    if not redis_client.set(key, '1', nx=True, ex=86400):
        return 'DUPLICATE_SKIPPED'
    producer.send(topic=f"notif.{event['priority']}", value=event)
    return 'ENQUEUED'

PRIORITY_TOPICS = {
    'P0': 'notif.p0.critical',
    'P1': 'notif.p1.transactional',
    'P2': 'notif.p2.bulk',
}

def select_topic(priority: str) -> str:
    if priority not in PRIORITY_TOPICS:
        raise ValueError(f'Unknown priority tier: {priority}')
    return PRIORITY_TOPICS[priority]

def dispatch_to_channel(channel: str, adapters: dict, payload: dict) -> dict:
    adapter = adapters.get(channel)
    if not adapter:
        raise ValueError(f'Unsupported channel: {channel}')
    return adapter.send(payload, timeout_sec=3.0)

import random

def compute_retry_delay(attempt: int, base: float = 2.0, cap: float = 300.0) -> float:
    exp = min(cap, base * (2 ** attempt))
    return random.uniform(exp * 0.5, exp)

def select_provider(primary_cb, primary: str, backup: str) -> str:
    if primary_cb.is_open():
        return backup
    return primary

def handle_provider_receipt(store, receipt: dict) -> None:
    if receipt['status'] in ('HARD_BOUNCE', 'UNREGISTERED_TOKEN'):
        store.deactivate_endpoint(receipt['user_id'], receipt['endpoint'])
    store.append_audit_log(receipt)
